// TP : un potentiomètre règle la luminosité d’une LED (PWM).
const int POT = A0;  // curseur du potentiomètre
const int LED = 9;   // broche PWM (~)

void setup() {
  Serial.begin(9600);
  pinMode(LED, OUTPUT);
}

void loop() {
  int valeur = analogRead(POT);               // 0 à 1023
  int lumiere = map(valeur, 0, 1023, 0, 255); // 0 à 255
  analogWrite(LED, lumiere);
  Serial.println(valeur);
  delay(100);
}
